#!/usr/bin/env python3
"""Checks that every store whose geometry was generated by a script carries the " (AI)" name suffix everywhere a player sees it.

Owner rule (2026-10-23): generated munition models are marked in the munition's name so that human-made and AI-made models can be told apart.
A store is generated when its Model or a RackAdapter Model is listed in tools/munition_models/ai_models.json (kept by
f16c_stores.mark_generated, which every generator calls), or when it carries "Generated": true. For each one the check requires
  - the store json "Name" ends with " (AI)" (at most 64 characters, the registry limit) and "Generated": true is present;
  - the dedicated launch gun profile (LaunchGunProfile, when no human-made store shares it) has a Name ending with " (AI)";
  - the native weapon (vehicles/<id>.json Weapons.<id>.Name) that an aircraft armament maps to the store (NativeWeaponIds) ends with " (AI)";
  - no lang entry shows the unmarked store name;
and the reverse: a store without generated geometry must not claim "Generated" or the suffix.

Usage: python tools/munition_models/ai_name_check.py [--fix] [--list]
  --fix   apply the suffix / provenance field to the store, gun and native weapon json (text edits keep the file layout)
  --list  print every store with its class (AI, human) and what marks it
Exit status 0 when nothing is wrong.
"""
import glob
import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.abspath(os.path.join(HERE, '..', '..'))
GEN = os.path.join(REPO, 'bvp', 'src', 'generated', 'resources')
DATA = os.path.join(GEN, 'data', 'berts_vehicle_pack', 'sbw')
STORES = os.path.join(DATA, 'aircraft_stores')
GUNS = os.path.join(DATA, 'guns')
VEHICLES = os.path.join(DATA, 'vehicles')
ARMAMENTS = os.path.join(DATA, 'aircraft_armaments')
GEO = os.path.join(GEN, 'assets', 'berts_vehicle_pack', 'custom_geo', 'aircraft_stores')
LANG = os.path.join(GEN, 'assets', 'berts_vehicle_pack', 'lang')
REGISTRY = os.path.join(HERE, 'ai_models.json')
SUFFIX = ' (AI)'
NAME_MAX = 64


def jload(path):
    with open(path, encoding='utf-8') as fh:
        return json.load(fh)


def base(ref):
    return os.path.basename(ref).replace('.geo.json', '') if ref else ''


def store_id(path):
    return 'berts_vehicle_pack:' + os.path.relpath(path, STORES).replace(os.sep, '/')[:-len('.json')]


def gun_path(ref):
    return os.path.join(GUNS, ref.split(':', 1)[1] + '.json')


def classify(d, models):
    """Why a store is generated: the model names that are in the registry (and 'Generated' when the field says so)."""
    why = [m for m in (base(d.get('Model')), base((d.get('RackAdapter') or {}).get('Model'))) if m in models]
    if d.get('Generated') is True:
        why.append('Generated')
    return why


def sub(text, anchor, old, new):
    """Replace the first '"Name": "old"' after anchor in text (layout-preserving json edit)."""
    start = text.index(anchor) if anchor else 0
    for ascii_only in (False, True):                        # files are written with raw or \\u-escaped non-ASCII
        needle = '"Name": ' + json.dumps(old, ensure_ascii=ascii_only)
        at = text.find(needle, start)
        if at >= 0:
            return text[:at] + '"Name": ' + json.dumps(new, ensure_ascii=ascii_only) + text[at + len(needle):]
    raise ValueError(f'Name "{old}" not found')


def main(argv):
    if hasattr(sys.stdout, 'reconfigure'):
        sys.stdout.reconfigure(encoding='utf-8')
    fix, listing = '--fix' in argv, '--list' in argv
    models = set(jload(REGISTRY)['models'])
    errors, fixed = [], 0
    stores = {}
    for path in sorted(glob.glob(os.path.join(STORES, '**', '*.json'), recursive=True)):
        rel = os.path.relpath(path, STORES).replace(os.sep, '/')
        if rel.startswith('modeled_store/'):
            continue                                        # the airframe's own baked stores: human-made, not munitions
        stores[store_id(path)] = (path, jload(path))
    for name in sorted(models):
        if not os.path.exists(os.path.join(GEO, name + '.geo.json')):
            errors.append(f'registry: no geo file for {name}')

    ai_stores, human_stores = {}, {}
    for sid, (path, d) in stores.items():
        why = classify(d, models)
        (ai_stores if why else human_stores)[sid] = (path, d, why)

    # ---- store names
    for sid, (path, d, why) in ai_stores.items():
        name = d.get('Name', '')
        if name.endswith(SUFFIX) and d.get('Generated') is True and len(name) <= NAME_MAX:
            continue
        if fix:
            text = open(path, encoding='utf-8').read()
            new_name = name if name.endswith(SUFFIX) else name + SUFFIX
            if new_name != name:
                text = sub(text, '', name, new_name)
            if d.get('Generated') is not True:
                text = text.replace(f'"Category": {json.dumps(d["Category"])},', f'"Category": {json.dumps(d["Category"])},\n  "Generated": true,', 1)
            with open(path, 'w', encoding='utf-8', newline='\n') as fh:
                fh.write(text)
            d.update(jload(path))
            fixed += 1
            if len(d['Name']) > NAME_MAX:
                errors.append(f'{sid}: name is {len(d["Name"])} characters (limit {NAME_MAX})')
        else:
            if not name.endswith(SUFFIX):
                errors.append(f'{sid}: name "{name}" lacks "{SUFFIX}"')
            if d.get('Generated') is not True:
                errors.append(f'{sid}: missing "Generated": true')
            if len(name) > NAME_MAX:
                errors.append(f'{sid}: name is {len(name)} characters (limit {NAME_MAX})')
    warnings = []
    for sid, (path, d, why) in human_stores.items():
        if d.get('Generated') or d.get('Name', '').endswith(SUFFIX):
            # not an error: a new generator may mark its store before its model is registered; ai_models.json must then list it
            warnings.append(f'{sid}: marked as AI but its model "{base(d.get("Model"))}" is not in ai_models.json (register it with '
                            f'f16c_stores.mark_generated, or drop the mark if the model was cut from a supplied one)')

    # ---- launch gun profiles used only by AI stores
    users = {}
    for sid, (path, d) in stores.items():
        if d.get('LaunchGunProfile'):
            users.setdefault(d['LaunchGunProfile'], []).append(sid)
    for ref, sids in sorted(users.items()):
        if not all(s in ai_stores for s in sids):
            continue                                        # shared with a human-made store: its name stays unmarked
        path = gun_path(ref)
        g = jload(path)
        if g.get('Name', '').endswith(SUFFIX):
            continue
        if fix:
            text = open(path, encoding='utf-8').read()
            text = sub(text, '', g['Name'], g['Name'] + SUFFIX)
            with open(path, 'w', encoding='utf-8', newline='\n') as fh:
                fh.write(text)
            fixed += 1
        else:
            errors.append(f'{ref}: gun Name "{g.get("Name")}" lacks "{SUFFIX}" (used by {", ".join(sids)})')

    # ---- native weapons fired from AI stores
    for arm_path in sorted(glob.glob(os.path.join(ARMAMENTS, '*.json'))):
        vid = os.path.basename(arm_path)[:-5]
        veh_path = os.path.join(VEHICLES, vid + '.json')
        if not os.path.exists(veh_path):
            continue
        arm = jload(arm_path)
        mapped = {}
        for mount in arm.get('Pairs', []) + arm.get('Singles', []):
            for sid, wids in (mount.get('NativeWeaponIds') or {}).items():
                for wid in (wids if isinstance(wids, list) else [wids]):
                    mapped.setdefault(wid, set()).add(sid)
        if not mapped:
            continue
        veh = jload(veh_path)
        text = None
        for wid, sids in sorted(mapped.items()):
            if not any(s in ai_stores for s in sids):
                continue
            w = (veh.get('Weapons') or {}).get(wid)
            if not w or 'Name' not in w:
                continue
            if w['Name'].endswith(SUFFIX):
                continue
            if fix:
                text = text if text is not None else open(veh_path, encoding='utf-8').read()
                text = sub(text, f'"{wid}": {{', w['Name'], w['Name'] + SUFFIX)
                fixed += 1
            else:
                errors.append(f'vehicles/{vid}.json: weapon {wid} "{w["Name"]}" is fired from an AI store and lacks "{SUFFIX}"')
        if text is not None:
            with open(veh_path, 'w', encoding='utf-8', newline='\n') as fh:
                fh.write(text)

    # ---- lang: no entry may show an AI store's unmarked name
    plain = {d['Name'][:-len(SUFFIX)] for _, d, _ in ai_stores.values() if d.get('Name', '').endswith(SUFFIX)}
    for lang in glob.glob(os.path.join(LANG, '*.json')):
        for key, value in jload(lang).items():
            if isinstance(value, str) and value in plain:
                errors.append(f'{os.path.basename(lang)}: {key} shows "{value}" without "{SUFFIX}"')

    if listing:
        for sid, (path, d, why) in sorted(ai_stores.items()):
            print(f'AI    {sid.split(":", 1)[1]:34} {d.get("Name")}   [{", ".join(why)}]')
        for sid, (path, d, why) in sorted(human_stores.items()):
            print(f'human {sid.split(":", 1)[1]:34} {d.get("Name")}')
    if fix:
        print(f'fixed {fixed} entries')
    print(f'ai_name_check: {len(ai_stores)} AI stores, {len(human_stores)} human-made / derived stores, {len(errors)} problems')
    for w in warnings:
        print('  WARN', w)
    for e in errors:
        print('  FAIL', e)
    return 1 if errors else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
